    private static JsonObject NativePolicy(ECDsa k)=>new(){["schema"]="RC_OWNER_CONSENT_POLICY_V1",["issuer"]="https://issuer.invalid/",["resource"]="https://resource.invalid/mcp",["ownerId"]="fixture-owner",["ownerSid"]="S-1-5-21-111-222-333-1001",["enrollmentEpoch"]="epoch:fixture",["helperSha256"]=new string('a',64),["signingPublicKeySpkiSha256"]=Convert.ToHexString(SHA256.HashData(k.ExportSubjectPublicKeyInfo())).ToLowerInvariant(),["clients"]=new JsonArray(new JsonObject{["clientId"]=Client,["redirectUris"]=new JsonArray("https://client.invalid/callback")},new JsonObject{["clientId"]=Client2,["redirectUris"]=new JsonArray("https://other-client.invalid/callback")}),["grantCatalog"]=new JsonArray(new JsonObject{["grantPolicyId"]="read-only",["grant"]=new JsonObject{["profileId"]="fixture",["rootPolicyId"]="fixture-root",["actions"]=new JsonArray("read_text"),["scopes"]=new JsonArray("commander:read")}})};
    private static JsonObject OAuthPolicy(ECDsa key,ECDsa ec,RSA rsa)=>new(){["schema"]="RC_PROTECTED_OAUTH_POLICY_V1",["issuer"]="https://issuer.invalid/",["tokenEndpoint"]=Endpoint,["resource"]="https://resource.invalid/mcp",["ownerId"]="fixture-owner",["enrollmentEpoch"]="epoch:fixture",["keyId"]="issuer:fixture",["signingPublicKeySpkiSha256"]=Convert.ToHexString(SHA256.HashData(key.ExportSubjectPublicKeyInfo())).ToLowerInvariant(),["clients"]=new JsonArray(new JsonObject{["clientId"]=Client,["jwks"]=new JsonArray(Jwk(ec,"ES256","ec-fixture"),Jwk(rsa,"RS256","rsa-fixture"))},new JsonObject{["clientId"]=Client2,["jwks"]=new JsonArray(Jwk(ec,"ES256","ec-fixture"))})};
    private sealed class Fixture:IDisposable
    {
        internal readonly string Path;internal readonly ECDsa Consent=ECDsa.Create(ECCurve.NamedCurves.nistP256),Issuer=ECDsa.Create(ECCurve.NamedCurves.nistP256),ClientEC=ECDsa.Create(ECCurve.NamedCurves.nistP256);internal readonly RSA ClientRSA=RSA.Create(2048);internal readonly byte[] NativeBytes,OAuthBytes;internal ProtectedIssuerState Store=null!;internal ProtectedOAuthExchange Exchange=null!;
