        private void Open(){Store=ProtectedIssuerState.OpenFixture(Path,NativeBytes,Consent.ExportSubjectPublicKeyInfoPem());Store.CrashAt=null;Exchange=ProtectedOAuthExchange.OpenFixture(Path,NativeBytes,OAuthBytes,Store,ECDsa.Create(Issuer.ExportParameters(true)));}
        internal void Reopen(){Exchange.Dispose();Open();}
        internal PendingSummary Pending(bool deny=false,string state="fixture-oauth-state-123456")
        {var request=new JsonObject{["response_type"]="code",["client_id"]=Client,["redirect_uri"]="https://client.invalid/callback",["resource"]="https://resource.invalid/mcp",["code_challenge_method"]="S256",["code_challenge"]=ConsentCore.B64(SHA256.HashData(Encoding.ASCII.GetBytes(Verifier))),["state"]=state,["grant_policy_id"]="read-only"};var p=Store.Begin(Bytes(request));
            if(deny){File.WriteAllText(System.IO.Path.Combine(Path,"receipts",p.RequestId+".json"),JsonSerializer.Serialize(new{status="OWNER_DENIED_OR_TIMEOUT",requestId=p.RequestId,requestDigest=p.RequestDigest,automaticRetryAllowed=false}));return p;}
            using var policy=ConsentCore.Strict(NativeBytes);var pending=ConsentCore.ValidatePending(File.ReadAllBytes(System.IO.Path.Combine(Path,"pending",p.RequestId+".json")),policy.RootElement,p.RequestId,DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());var statement=ConsentCore.Statement(pending,DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),ConsentCore.B64(RandomNumberGenerator.GetBytes(32)));var data=Encoding.UTF8.GetBytes("RC_OWNER_OAUTH_CONSENT_V1\n").Concat(statement).ToArray();var signature=Consent.SignData(data,HashAlgorithmName.SHA256,DSASignatureFormat.Rfc3279DerSequence);using var s=JsonDocument.Parse(statement);File.WriteAllBytes(System.IO.Path.Combine(Path,"receipts",p.RequestId+".json"),ExchangeJournal.Json(w=>{w.WritePropertyName("statement");w.WriteRawValue(statement,false);w.WriteString("signature",ConsentCore.B64(signature));}));return p;
        }
        internal string Assertion(string alg="ES256",string? jti=null,string? audience=null,bool wrongSignature=false,bool expired=false,bool addJku=false,string client=Client)
        {var at=DateTimeOffset.UtcNow.ToUnixTimeSeconds()-(expired?120:0);var h=new JsonObject{["alg"]=alg,["kid"]=alg=="RS256"?"rsa-fixture":"ec-fixture",["typ"]="JWT"};if(addJku)h["jku"]="https://untrusted.invalid/jwks";var c=new JsonObject{["iss"]=client,["sub"]=client,["aud"]=audience??Endpoint,["iat"]=at,["exp"]=at+60,["jti"]=jti??ConsentCore.B64(RandomNumberGenerator.GetBytes(24))};var prefix=ConsentCore.B64(Bytes(h))+"."+ConsentCore.B64(Bytes(c));byte[] signature;if(alg=="RS256")signature=ClientRSA.SignData(Encoding.UTF8.GetBytes(prefix),HashAlgorithmName.SHA256,RSASignaturePadding.Pkcs1);else{using var wrong=wrongSignature?ECDsa.Create(ECCurve.NamedCurves.nistP256):null;signature=(wrong??ClientEC).SignData(Encoding.UTF8.GetBytes(prefix),HashAlgorithmName.SHA256,DSASignatureFormat.IeeeP1363FixedFieldConcatenation);}return prefix+"."+ConsentCore.B64(signature);}
