        public void Dispose(){Exchange.Dispose();Consent.Dispose();Issuer.Dispose();ClientEC.Dispose();ClientRSA.Dispose();}
    }
    private static void Crash(Fixture f,string stage,string requestId,JsonObject? token=null)
    {var psi=new ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};foreach(var arg in new[]{"--crash",f.Path,stage,requestId})psi.ArgumentList.Add(arg);if(token!=null)psi.Environment["R78_EPHEMERAL_TOKEN_REQUEST"]=Encoding.UTF8.GetString(Bytes(token));using var p=Process.Start(psi)??throw new Exception("CHILD_START");ConsentCore.Need(p.WaitForExit(15000)&&p.ExitCode==72,"OWN_CHILD_EXIT");}
