        Check("one-use code remains consumed after reopen",()=>{using var f=new Fixture();var c=f.Exchange.AuthorizeAfterNativeConsent(f.Pending().RequestId);f.Exchange.ExchangeToken(Bytes(f.Token(c)));f.Reopen();Denies(()=>f.Exchange.ExchangeToken(Bytes(f.Token(c))),"CODE_CONSUMED_EXPIRED_OR_REVOKED");});
